<?php declare(strict_types=1);require_once __DIR__.'/includes/init.php';require_role('encargado','docente');$token=trim((string)($_GET['token']??''));$s=db()->prepare('SELECT e.*,s.nombre sala,s.ubicacion FROM equipos e JOIN salas s ON s.id=e.sala_id WHERE e.qr_token=:t AND e.activo=1 AND e.eliminado_en IS NULL AND s.eliminado_en IS NULL LIMIT 1');$s->execute(['t'=>$token]);$e1=$s->fetch();if(!$e1){http_response_code(404);exit('Equipo no encontrado.');}log_activity('Ficha abierta mediante QR','equipos',(int)$e1['id']);$pageTitle='Ficha técnica del equipo';require __DIR__.'/includes/header.php';?>
<section class="grid grid-2"><article class="card"><div class="card-header"><h2><?=e($e1['codigo_inventario'])?></h2><?=status_badge($e1['estado'])?></div><div class="card-body"><div class="grid grid-2"><div><strong>Sala</strong><div><?=e($e1['sala'])?></div></div><div><strong>Tipo</strong><div><?=e(equipment_type_label($e1['tipo']))?></div></div><div><strong>Marca</strong><div><?=e($e1['marca']??'-')?></div></div><div><strong>Sistema</strong><div><?=e($e1['sistema_operativo']??'-')?></div></div></div><?php if($e1['observaciones']):?><div class="ticket-message mt-3"><?=e($e1['observaciones'])?></div><?php endif;?></div></article><article class="card"><div class="card-header"><h2>Acciones</h2></div><div class="card-body quick-actions"><?php if(is_docente()):?><a class="quick-action" href="<?=e(url('docente/nuevo_ticket.php?equipo_id='.(int)$e1['id']))?>"><span>Reportar falla</span><strong>a</strong></a><?php endif;?><a class="quick-action" href="<?=e(url('tickets.php'))?>"><span>Ver tickets</span><strong>a</strong></a></div></article></section><?php require __DIR__.'/includes/footer.php';?>
